SELECT count(*) AS requests, count(booth_id) AS with_booth_id, count(*) FILTER (WHERE booth_id ~ '[0-9]{5}') AS five_digit, count(*) FILTER (WHERE booth_id ~ '[0-9]{5}' AND EXISTS (SELECT 1 FROM "FactoryPlanningBooth" p WHERE p."boothUniqueId" = substring(r.booth_id from '([0-9]{5})'))) AS in_planning, count(user_id) AS with_user_id, count(*) FILTER (WHERE user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "User" u WHERE u.id = r.user_id)) AS user_orphans FROM rp_requests r
